import { currentDictation, currentBlocks, escapeHtml as e, time, wordCount } from './store.js';
import { documentState } from './document-state.js';
import { dictationCoverage } from './evidence.js';
import { reviewItems } from './revision-store.js';
import { pipelineStrip, pipelineDetails } from './pipeline-view.js';
import { profileCard, profileSelector } from './profile-view.js';
import { profileContext, selectedProfile } from './profile-store.js';
import { icon } from './icons.js';
const button = (action, text, cls = '', extra = '') => `<button class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const code = v => `<pre class="code-block">${e(JSON.stringify(v, null, 2))}</pre>`;
function overview(s) {
  const d = currentDictation(s), ds = documentState(s), c = dictationCoverage(s, d.id), assets = s.audioAssets.filter(a => a.dictationId === d.id), pending = reviewItems(s).filter(i => i.dictationId === d.id && i.state === 'Pending');
  return `${pipelineStrip(s, d.id)}<div class="hub-overview-grid"><section class="hub-card"><div class="section-heading"><h3>Audio & evidence</h3><span>${assets.length} audio references</span></div><dl class="hub-facts"><div><dt>Source</dt><dd>${e(d.type)}</dd></div><div><dt>Duration</dt><dd>${time(d.duration)}</dd></div><div><dt>Recognized target intervals</dt><dd>${time(c.evidence)} / ${time(d.duration)}</dd></div><div><dt>Document intervals</dt><dd>${time(c.document)} / ${time(d.duration)}</dd></div><div><dt>Retained attempts</dt><dd>${s.attempts.filter(a => s.spans.some(p => p.dictationId === d.id && p.id === a.spanId)).length}</dd></div></dl><div class="hub-card-footer">${button('dictation-tab', 'Inspect audio & recognition', 'small-button', 'data-value="audio"')}</div></section><section class="hub-card"><div class="section-heading"><h3>Working document</h3><span>v${ds.version}</span></div><dl class="hub-facts"><div><dt>Words / passages</dt><dd>${wordCount(currentBlocks(s))} / ${currentBlocks(s).length}</dd></div><div><dt>Human-edited passages</dt><dd>${currentBlocks(s).filter(b => s.editedBlocks.has(b.id)).length} protected</dd></div><div><dt>Review items</dt><dd>${pending.length} pending</dd></div><div><dt>Revision history</dt><dd>${ds.history.length} snapshots</dd></div></dl><div class="human-write-policy">Human edits are accepted directly. Correctors only propose changes.</div><div class="hub-card-footer">${button('edit-document', 'Open document editor', 'small-button')}${button('review', 'Review proposals', 'small-button')}</div></section>${profileCard(s, 'recognizer')}${profileCard(s, 'corrector')}</div><details class="hub-domain"><summary>Dictation, profiles, runs and jobs</summary><p>A dictation is the human work item. A profile specifies a model and context prompt. Each run freezes the chosen profile and primer input. Independent jobs perform the run’s stages; recognition jobs own audio spans and attempts. Correction jobs return proposals for human review.</p></details>`;
}
function audio(s) {
  const d = currentDictation(s), assets = s.audioAssets.filter(a => a.dictationId === d.id);
  return `<section class="hub-card hub-audio"><div class="section-heading"><h3>Audio source</h3><span>Visual preview · no sample audio</span></div><div class="hub-waveform">${d.waveform.map(h => `<i style="height:${h}px"></i>`).join('')}</div><div class="hub-audio-footer"><span class="mono">00:00–${time(d.duration)}</span>${button('dictation-preview', icon('play') + ' Open timeline preview', 'small-button')}</div>${assets.map(a => `<div class="hub-audio-asset"><strong>${e(a.name)}</strong><span>${e(a.id)} · ${a.sampleRate || 48000} Hz · ${a.channels || 1} channel · ${time(a.duration)}</span></div>`).join('')}</section><div class="hub-recognition-callout"><div><h3>Start recognition for this dictation</h3><p>Select a recognizer profile and audio plan. Results retain their own frozen inputs; the working document is preserved.</p></div>${button('new-recognition', 'Start recognition', 'primary')}</div>${pipelineStrip(s, d.id)}${pipelineDetails(s, d.id, 'dictation-inspect-job')}`;
}
function documents(s) {
  const ds = documentState(s), changes = s.changes.filter(c => c.dictationId === s.dictationId), pending = changes.filter(c => c.state === 'pending');
  return `<div class="hub-doc-actions">${button('edit-document', 'Edit working document', 'primary')}${button('review', `Review ${pending.length} correction proposals`)}${button('revisions', 'Suggest corrections')}${button('assembly', 'Assembly preview')}${button('export', 'Export document')}</div><div class="human-write-policy wide-policy">Corrector results are proposals. The document changes when you type or explicitly accept a proposal; suggestions never apply themselves.</div><div class="hub-document-preview hub-card"><div class="section-heading"><h3>Working document</h3><span>v${ds.version} · ${wordCount(currentBlocks(s))} words</span></div>${currentBlocks(s).slice(0, 3).map(b => `<p>${e(b.text)}</p>`).join('') || '<p class="technical-note">No document text yet. Recognition evidence and assembly are separate stages.</p>'}${currentBlocks(s).length > 3 ? '<span class="technical-note">Open the editor for the complete document.</span>' : ''}</div><div class="hub-overview-grid"><section class="hub-card"><div class="section-heading"><h3>Revision history</h3><span>${ds.history.length} snapshots</span></div>${ds.history.slice(-8).reverse().map(v => `<div class="hub-history-row"><strong>v${v.version} · ${e(v.type)}</strong><span>${e(v.time)} · ${v.blocks.length} passages</span></div>`).join('')}</section><section class="hub-card"><div class="section-heading"><h3>Application journal</h3><span>Human actions and guards</span></div>${ds.journal.slice(-8).reverse().map(j => `<div class="hub-history-row"><strong>${e(j.action)} · ${e(j.outcome)}</strong><span>${e(j.time)} · ${e(j.detail)}</span></div>`).join('') || '<p class="technical-note">No document operations in this session.</p>'}</section></div>`;
}
function context(s) {
  const primer = s.primers[s.dictationId];
  return `<div class="hub-overview-grid">${profileCard(s, 'recognizer')}${profileCard(s, 'corrector')}</div><section class="hub-card hub-primer"><div class="section-heading"><h3>Dictation topic primer</h3><span>v${primer.version} · this dictation</span></div><p class="technical-note">The reusable profile prompt and dictation primer are combined at run preparation. Confirmed terms become keywords where supported, or prompt text otherwise.</p><textarea id="topic-editor" rows="4" aria-label="Dictation topic primer">${e(primer.topic)}</textarea><div class="hub-card-footer">${button('save-topic', 'Save primer version', 'small-button')}${button('dictation-context-editor', 'Manage terminology', 'small-button')}</div></section><div class="hub-overview-grid"><details class="hub-card compiled-context" open><summary>Compiled recognizer input</summary>${code(profileContext(s, selectedProfile(s, 'recognizer')))}</details><details class="hub-card compiled-context" open><summary>Compiled corrector input</summary>${code(profileContext(s, selectedProfile(s, 'corrector')))}</details></div>`;
}
function advanced(s) {
  const d = currentDictation(s), jobs = s.jobs.filter(j => j.dictationId === d.id && j.kind === 'ASR');
  return `<div class="advanced-intro"><h2>Advanced tools</h2><p>Use for targeted recognition failures, comparisons, and execution inspection. Normal dictation work stays in the document editor.</p></div><details class="hub-card section-rerun"><summary><strong>Re-recognize an audio section</strong><span>Rare operation · new evidence; document preserved</span></summary><p class="technical-note">Select an exact target. Surrounding evidence may overlap adjacent input windows. A separate recognition job retains earlier attempts and any human-edited text.</p><div class="setting-grid"><label class="setting-field"><span>Target start · seconds</span><input id="section-start" type="number" min="0" max="${d.duration}" value="${Math.max(0, s.position - 5)}"/></label><label class="setting-field"><span>Target end · seconds</span><input id="section-end" type="number" min="0" max="${d.duration}" value="${Math.min(d.duration, s.position + 25)}"/></label></div><label class="setting-field"><span>Recognizer profile</span>${profileSelector(s, 'recognizer', d.id, 'section-profile')}</label><div class="setting-grid"><label class="setting-field"><span>Evidence before · seconds</span><input id="section-before" type="number" min="0" max="120" value="6"/></label><label class="setting-field"><span>Evidence after · seconds</span><input id="section-after" type="number" min="0" max="120" value="6"/></label></div>${button('section-recognition', 'Create section recognition preview', 'small-button')}</details><details class="hub-card advanced-executions"><summary><strong>Execution controls & fixture simulation</strong><span>Retries, dispatch, cancellation and illustrative responses</span></summary><p class="technical-note">These controls operate on existing jobs of this dictation. They do not apply recognition or corrector output to the document.</p>${jobs.map(j => `<article class="hub-execution"><header><div><strong>${e(j.title)}</strong><small>${e(j.id)} · ${e(j.state)}</small></div>${button('dictation-inspect-job', 'Inspect pipeline', 'small-button', `data-id="${e(j.id)}"`)}</header><div class="hub-execution-controls">${!['Complete', 'Cancelled'].includes(j.state) ? `${button('dispatch-ready', 'Dispatch ready spans', 'small-button', `data-id="${j.id}"`)}${button('activity-toggle-job', j.state === 'Paused' ? 'Resume' : 'Pause dispatch', 'small-button', `data-id="${j.id}"`)}${button('cancel-job', 'Cancel', 'small-button danger-text', `data-id="${j.id}"`)}` : ''}</div><div class="hub-span-tools">${j.spanIds.map(id => { const span = s.spans.find(p => p.id === id), attempts = s.attempts.filter(a => a.jobId === j.id && a.spanId === id); return `<div><span class="mono">${time(span.target[0])}–${time(span.target[1])}</span><span>${attempts.length} attempts</span>${button('dictation-retry', 'Retry / change input', 'small-button', `data-id="${id}" data-job="${j.id}"`)}${attempts.filter(a => ['Queued', 'Running'].includes(a.state)).map(a => `${button('attempt-success', 'Simulate success', 'small-button', `data-id="${a.id}"`)}${button('attempt-failure', 'Simulate failure', 'small-button', `data-id="${a.id}"`)}`).join('')}</div>`; }).join('')}</div></article>`).join('') || '<p class="technical-note">No recognition executions.</p>'}</details>`;
}
export function dictationHub(s) {
  const d = currentDictation(s), pending = reviewItems(s).filter(i => i.dictationId === d.id && i.state === 'Pending').length;
  return `<main id="document" class="dictation-hub" tabindex="-1"><header class="dictation-heading"><div><div class="hub-breadcrumb">${button('edit-document', 'Workspace', 'text-button small-button')}<span>/</span><span>Dictation</span><select id="hub-dictation" aria-label="Open dictation">${s.dictations.map(q => `<option value="${e(q.id)}" ${q.id === d.id ? 'selected' : ''}>${e(q.title)}</option>`).join('')}</select></div><h1>${e(d.title)}</h1><div class="hub-heading-meta"><span>${time(d.duration)}</span><span>${e(d.type)}</span><span>${e(d.language)}</span>${d.tags.map(t => `<span class="badge">${e(t)}</span>`).join('')}</div></div><div class="dictation-heading-actions">${button('edit-document', 'Edit document')}${button('review', `Review ${pending}`)}${button('new-recognition', 'Start recognition', 'primary')}</div></header><nav class="dictation-tabs" aria-label="Dictation sections">${[['overview', 'Overview'], ['audio', 'Audio & recognition'], ['documents', 'Documents & review'], ['profiles', 'Profiles & context'], ['advanced', 'Advanced']].map(([id, text]) => `<button data-action="dictation-tab" data-value="${id}" class="${s.dictationTab === id ? 'active' : ''}">${text}</button>`).join('')}</nav><div class="dictation-hub-scroll">${s.dictationTab === 'audio' ? audio(s) : s.dictationTab === 'documents' ? documents(s) : s.dictationTab === 'profiles' ? context(s) : s.dictationTab === 'advanced' ? advanced(s) : overview(s)}</div></main>`;
}
export function recognitionForm(s) {
  const d = currentDictation(s);
  return `<div class="recognition-owner"><span>DICTATION</span><strong>${e(d.title)}</strong><small>${e(d.id)} · ${time(d.duration)}</small></div><label class="setting-field"><span>Recognizer profile</span>${profileSelector(s, 'recognizer', d.id, 'run-profile')}</label><div class="setting-grid"><label class="setting-field"><span>Audio plan</span><select id="run-plan"><option value="single">Whole target</option><option value="partitioned" selected>Partitioned targets</option><option value="growing">Growing input windows</option></select></label><label class="setting-field"><span>Target spans</span><input id="run-parts" type="number" min="1" max="100" value="${Math.max(1, Math.ceil(d.duration / 30))}"/></label></div><p class="technical-note">Scope: entire retained recording, 00:00–${time(d.duration)}. Section re-recognition is available under Advanced.</p><div id="run-input-preview" class="quiet-note">The chosen profile and current primer are frozen for this recognition run. Results are stored as evidence.</div><details class="profile-prompt-preview"><summary>Recognizer snapshot preview</summary><div id="run-profile-preview">${code(profileContext(s, selectedProfile(s, 'recognizer')))}</div></details>`;
}
